public void onFramesPasted(int num) {
    int currentIndex = this.mCurrentScene.getCurrentIndex();
    this.mStickmanView.onFrameChanged(currentIndex, currentIndex);
    this.mDualNav.update(this.mCurrentScene);
    updateWidgets();
    flashActiveFrame(true);
    UIUtils.niceToast(String.format(Locale.getDefault(), getString(com.zalivka.animation2.R.string.pasted_frames_from_buffer), Integer.valueOf(num)), UIUtils.TOAST_KIND.INFO);
}
